package com.dreamseekers;
import com.solegendary.reignofnether.unit.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.ai.navigation.PathNavigation;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;
@GameTestHolder(DreamseekersMod.MOD_ID) @PrefixGameTestTemplate(false)
public final class AaroncosFlightGameTests {
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=1140) public static void leftWideMoveShift(GameTestHelper h){AaroncosBoundaryGameTests.move(h,false);}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=1140) public static void rightWideMoveShift(GameTestHelper h){AaroncosBoundaryGameTests.move(h,true);}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=940) public static void leftReverseDiagonalAndSameTickABA(GameTestHelper h){reverse(h,false);}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=940) public static void rightReverseDiagonalAndSameTickABA(GameTestHelper h){reverse(h,true);}
 static void reverse(GameTestHelper h,boolean right){var f=new AaroncosTestFixture(h,"Reverse"+right);var m=f.hand(right,"Owner",34,1,30);var a=f.p(19,0,16);var b=f.p(44,0,34);var s=f.ready(m).thenExecute(()->{f.order(m,UnitAction.MOVE,a);f.order(m,UnitAction.MOVE,b);f.order(m,UnitAction.MOVE,a);});for(int i=1;i<=740;i++)s.thenIdle(1).thenExecute(()->{h.assertTrue(h.getLevel().noCollision(m),"reverse diagonal remains solid");var t=AaroncosTestFixture.unit(m).getMoveGoal().getMoveTarget();h.assertTrue(t==null||t.equals(a.above()),"same tick A B A never replays superseded B");});s.thenExecute(()->h.assertTrue(f.arrived(m,a),"true reverse/diagonal .8-foot arrival and cleared command "+f.describe(m))).thenSucceed();}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=920) public static void leftThreeCellGapRejectsThenFourCellOpens(GameTestHelper h){gap(h,false);}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=920) public static void rightThreeCellGapRejectsThenFourCellOpens(GameTestHelper h){gap(h,true);}
 static void gap(GameTestHelper h,boolean right){var f=new AaroncosTestFixture(h,"Gap"+right);for(int z=0;z<44;z++)for(int y=1;y<14;y++)f.set(20,y,z,Blocks.STONE);for(int z=19;z<=21;z++)for(int y=1;y<=3;y++)f.set(20,y,z,Blocks.AIR);var m=f.hand(right,"Owner",9,1,20);var dest=f.p(31,0,20);var s=f.ready(m).thenExecute(()->f.order(m,UnitAction.MOVE,dest));for(int i=1;i<=650;i++){final int t=i;s.thenIdle(1).thenExecute(()->{h.assertTrue(h.getLevel().noCollision(m),"exact3.5 body never squeezes through collision");if(t<160)h.assertTrue(m.getX()<f.p(20,0,0).getX(),"cannot fit3wide3high");if(t==160)for(int z=18;z<=21;z++)for(int y=1;y<=4;y++)f.set(20,y,z,Blocks.AIR);});}s.thenExecute(()->h.assertTrue(f.arrived(m,dest),"unchanged pending order crosses actual4wide4high opening and arrives "+f.describe(m))).thenSucceed();}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=780) public static void leftActualFlightOverTwoHighBarrier(GameTestHelper h){barrier(h,false);}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=780) public static void rightActualFlightOverTwoHighBarrier(GameTestHelper h){barrier(h,true);}
 static void barrier(GameTestHelper h,boolean right){var f=new AaroncosTestFixture(h,"Barrier"+right);for(int x=2;x<=40;x++)for(int y=1;y<14;y++){f.set(x,y,7,Blocks.STONE);f.set(x,y,14,Blocks.STONE);}for(int z=8;z<=13;z++)for(int y=1;y<=2;y++)f.set(20,y,z,Blocks.STONE);var m=f.hand(right,"Owner",7,1,10);var dest=f.p(32,0,10);double[] max={m.getY()};var s=f.ready(m).thenExecute(()->f.order(m,UnitAction.MOVE,dest));for(int i=0;i<650;i++)s.thenIdle(1).thenExecute(()->{h.assertTrue(h.getLevel().noCollision(m)&&!m.noPhysics,"real full-width collision each tick");max[0]=Math.max(max[0],m.getY());h.assertTrue(m.getY()<f.p(0,5,0).getY(),"fixed low altitude band, not stock +10");});s.thenExecute(()->h.assertTrue(max[0]>=f.p(0,3,0).getY()-.05&&f.arrived(m,dest),"truly over barrier then arrive "+f.describe(m)+" max="+max[0])).thenSucceed();}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=780) public static void leftStopInvalidatesRealPendingRecomputeAndNewMoveWorks(GameTestHelper h)throws Exception{stop(h,false);}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_flight",timeoutTicks=780) public static void rightStopInvalidatesRealPendingRecomputeAndNewMoveWorks(GameTestHelper h)throws Exception{stop(h,true);}
 static void stop(GameTestHelper h,boolean right)throws Exception{var f=new AaroncosTestFixture(h,"Stop"+right);var m=f.hand(right,"Owner",6,1,8);var dest=f.p(21,0,25);var delayed=PathNavigation.class.getDeclaredField("hasDelayedRecomputation");delayed.setAccessible(true);Vec3[] stop={null};var s=f.ready(m).thenExecute(()->f.order(m,UnitAction.MOVE,f.p(45,0,8))).thenIdle(40).thenExecute(()->{var n=m.getNavigation();h.assertTrue(!n.isDone()&&n.getTargetPos()!=null,"real active route before genuine delayed recompute");n.recomputePath();n.recomputePath();try{h.assertTrue(delayed.getBoolean(n),"actual second recompute sets vanilla pending, no field injection");}catch(Exception e){throw new RuntimeException(e);}new UnitActionItem(AaroncosTestFixture.unit(m).getOwnerName(),UnitAction.STOP,-1,new int[]{m.getId()},BlockPos.ZERO,BlockPos.ZERO).action(h.getLevel());stop[0]=m.position();});for(int i=0;i<45;i++)s.thenIdle(1).thenExecute(()->{try{h.assertTrue(m.getNavigation().isDone()&&m.getNavigation().getTargetPos()==null&&!delayed.getBoolean(m.getNavigation())&&AaroncosTestFixture.unit(m).getMoveGoal().getMoveTarget()==null&&m.position().distanceToSqr(stop[0])<.05,"STOP spans native21tick window without stale route");}catch(Exception e){throw new RuntimeException(e);}});s.thenExecute(()->f.order(m,UnitAction.MOVE,dest)).thenIdle(520).thenExecute(()->h.assertTrue(f.arrived(m,dest),"new MOVE after genuine STOP still works "+f.describe(m))).thenSucceed();}
 @AfterBatch(batch="aaron_flight") public static void cleanup(ServerLevel l){AaroncosTestFixture.cleanup(l);}
}
